package org.tzi.use.plugins.jacamo.semantics;
public class AwaitRegressionArtifact extends cartago.Artifact {public static volatile java.util.concurrent.CountDownLatch suspended=new java.util.concurrent.CountDownLatch(1);boolean released;public void init(){defineObsProperty("p",0);}@cartago.OPERATION public void reset(){released=false;getObsProperty("p").updateValue(0);}@cartago.OPERATION public void slow(){getObsProperty("p").updateValue(1);suspended.countDown();await("released");getObsProperty("p").updateValue(getObsProperty("p").intValue()+1);}@cartago.OPERATION public void fast(){getObsProperty("p").updateValue(getObsProperty("p").intValue()+1);}@cartago.OPERATION public void unblock(){released=true;}@cartago.GUARD public boolean released(){return released;}}
